  function clip(poly,level,keepAbove){const out=[];for(let i=0;i<poly.length;i++){const a=poly[i],b=poly[(i+1)%poly.length],ia=keepAbove?a[1]>=level:a[1]<=level,ib=keepAbove?b[1]>=level:b[1]<=level;if(ia)out.push(a);if(ia!==ib){const t=(level-a[1])/(b[1]-a[1]);out.push([a[0]+(b[0]-a[0])*t,level,a[2]+(b[2]-a[2])*t])}}return out}
  for(let i=0;i<wallData.length;i+=18){const get=j=>[wallData[i+j],wallData[i+j+1],wallData[i+j+2]],a=get(0),c=get(3),d=get(6),b=get(15),x=(a[0]+c[0])/2,z=(a[2]+c[2])/2;const building=previous&&contains(previous,x,z)?previous:(buildingCells.get(Math.floor(x/30)+','+Math.floor(z/30))||[]).find(v=>contains(v,x,z));previous=building;const base=building?building.ground-datum:Math.min(a[1],c[1]),dx=c[0]-a[0],dz=c[2]-a[2],len=Math.hypot(dx,dz)||1,flip=building?.profile.flip||1,u=(x*dx/len+z*dz/len)*flip/7,bay=Math.floor(u),minY=Math.min(a[1],c[1]),maxY=Math.max(b[1],d[1]);for(let f=Math.floor((minY-base)/3.4);f<Math.ceil((maxY-base)/3.4);f++){let poly=clip([a,c,d,b],base+f*3.4,true);if(poly.length<3)continue;poly=clip(poly,base+(f+1)*3.4,false);if(poly.length<3)continue;const style=building?facadeStyle(building.profile,building.id,bay,(f+.5)*3.4):0,batch=batches[style];for(let j=1;j<poly.length-1;j++)for(const point of [poly[0],poly[j],poly[j+1]]){const[x,y,z]=point;batch.p.push(x,y,z);batch.uv.push((x*dx/len+z*dz/len)*flip/7,1-(y-base)/3.4);const shade=T.MathUtils.lerp(.8,1,Math.min(1,Math.max(0,(y-base)/1.8)));batch.c.push(shade,shade,shade)}}}
